  /// 検索バー＋分野フィルタ＋ソート
  Widget _searchAndSortBar(ThemeData theme) {
    return Column(
      children: [
        // 検索バー（controller/focusを保持して安定化）
        TextField(
          controller: _searchController,
          focusNode: _searchFocusNode,
          decoration: const InputDecoration(
            hintText: '分野名・出題形式・問題文で検索',
