// lib/screens/past_exam/past_exam_list_screen.dart
import 'package:flutter/material.dart';

import '../../models/nurai_question.dart';
import '../../models/past_exam_history.dart';
import '../../services/past_exam_repository.dart';
import '../../theme/app_theme.dart';
import '../../widgets/base_scaffold.dart';
import 'past_exam_question_screen.dart';

class PastExamListScreen extends StatefulWidget {
  const PastExamListScreen({
    super.key,
    required this.examId,
    required this.examTitle,
    required this.totalQuestions,
  });

  final String examId;      // '111'
  final String examTitle;   // '第111回（2022年）'
  final int totalQuestions; // 年度合計（表示用）

  @override
  State<PastExamListScreen> createState() => _PastExamListScreenState();
}

class _PastExamListScreenState extends State<PastExamListScreen> {
  bool _loading = true;

  List<PastExamAnswerRecord> _records = const [];

  final Map<String, int> _totalByPartKey = {};
  final Map<String, bool> _availableByPartKey = {};

  @override
  void initState() {
    super.initState();
    _load();
    PastExamHistory.instance.versionListenable.addListener(_onHistoryChanged);
  }

  @override
  void dispose() {
    PastExamHistory.instance.versionListenable.removeListener(_onHistoryChanged);
    super.dispose();
  }

  void _onHistoryChanged() {
    _loadHistoryOnly();
  }

  Future<void> _load() async {
    if (!mounted) return;
    setState(() => _loading = true);

    await _loadHistoryOnly();
    await _probeParts();

    if (!mounted) return;
    setState(() => _loading = false);
  }

  Future<void> _loadHistoryOnly() async {
    try {
      final list = await PastExamHistory.instance.recordsForExam(widget.examId);
      if (!mounted) return;
      setState(() => _records = list);
    } catch (_) {
      if (!mounted) return;
      setState(() => _records = const []);
    }
  }

  static const _partMetas = <_PartMeta>[
    _PartMeta(partKey: 'hisshu_am', label: '必修問題', timeLabel: '午前'),
    _PartMeta(partKey: 'hisshu_pm', label: '必修問題', timeLabel: '午後'),
    _PartMeta(partKey: 'ippan_am', label: '一般問題', timeLabel: '午前'),
    _PartMeta(partKey: 'ippan_pm', label: '一般問題', timeLabel: '午後'),
    _PartMeta(partKey: 'jokyo_am', label: '状況設定問題', timeLabel: '午前'),
    _PartMeta(partKey: 'jokyo_pm', label: '状況設定問題', timeLabel: '午後'),
  ];

  List<_PartMeta> _partsOf(String timeLabel) {
    return _partMetas.where((p) => p.timeLabel == timeLabel).toList();
  }

  Future<void> _probeParts() async {
    _totalByPartKey.clear();
    _availableByPartKey.clear();

    for (final p in _partMetas) {
      try {
        final list = await PastExamRepository.instance.load(
          examId: widget.examId,
          partKey: p.partKey,
        );
        _availableByPartKey[p.partKey] = list.isNotEmpty;
        _totalByPartKey[p.partKey] = list.length;
      } catch (_) {
        _availableByPartKey[p.partKey] = false;
        _totalByPartKey[p.partKey] = 0;
      }
    }

    if (!mounted) return;
    setState(() {});
  }

  int _solvedCountForPartKey(String partLabelWithTime) {
    // partLabel の一致でカウント（保存側 PastExamQuestionScreen に partLabel を渡している前提）
    return _records.where((r) {
      final pl = (r.partLabel ?? '').trim();
      if (pl.isNotEmpty) return pl == partLabelWithTime;

      // フォールバック（古いデータ向け）
      final k = r.questionKey;
      return k.contains(partLabelWithTime);
    }).length;
  }

  int _solvedCountForPart(_PartMeta p) => _solvedCountForPartKey('${p.label} ${p.timeLabel}');

  int _totalCountForTime(String timeLabel) {
    var total = 0;
    for (final p in _partsOf(timeLabel)) {
      total += (_totalByPartKey[p.partKey] ?? 0);
    }
    return total;
  }

  int _solvedCountForTime(String timeLabel) {
    var solved = 0;
    for (final p in _partsOf(timeLabel)) {
      solved += _solvedCountForPart(p);
    }
    return solved;
  }

  bool _hasAnyDataForTime(String timeLabel) {
    return _partsOf(timeLabel).any((p) => (_availableByPartKey[p.partKey] ?? false));
  }

  Future<void> _openPart(_PartMeta p) async {
    try {
      final questions = await PastExamRepository.instance.load(
        examId: widget.examId,
        partKey: p.partKey,
      );

      if (!mounted) return;

      if (questions.isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('このパートの過去問データが見つかりませんでした（${p.partKey}.json）')),
        );
        return;
      }

      Navigator.of(context).push(
        MaterialPageRoute(
          builder: (_) => PastExamQuestionScreen(
            examTitle: widget.examTitle,
            partLabel: '${p.label} ${p.timeLabel}',
            questions: questions,
          ),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('過去問の読み込みに失敗しました: $e')),
      );
    }
  }

  Future<void> _openTimeAll(String timeLabel) async {
    final parts = _partsOf(timeLabel).where((p) => (_availableByPartKey[p.partKey] ?? false)).toList();

    if (parts.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('$timeLabel の過去問データが見つかりませんでした')),
      );
      return;
    }

    try {
      final merged = <NuraiQuestion>[];

      for (final p in parts) {
        final list = await PastExamRepository.instance.load(
          examId: widget.examId,
          partKey: p.partKey,
        );
        merged.addAll(list);
      }

      if (!mounted) return;

      if (merged.isEmpty) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('$timeLabel の過去問データが見つかりませんでした')),
        );
        return;
      }

      Navigator.of(context).push(
        MaterialPageRoute(
          builder: (_) => PastExamQuestionScreen(
            examTitle: widget.examTitle,
            partLabel: timeLabel, // まとめ解答
            questions: merged,
          ),
        ),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('過去問の読み込みに失敗しました: $e')),
      );
    }
  }

  void _showPartsSheet(String timeLabel) {
    final parts = _partsOf(timeLabel).where((p) => (_availableByPartKey[p.partKey] ?? false)).toList();

    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) {
        final theme = Theme.of(context);

        return SafeArea(
          child: Container(
            margin: const EdgeInsets.fromLTRB(12, 0, 12, 12),
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 10),
            decoration: BoxDecoration(
              color: theme.colorScheme.surface,
              borderRadius: BorderRadius.circular(18),
              border: Border.all(color: Colors.black12),
            ),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                // ヘッダー
                Row(
                  children: [
                    Expanded(
                      child: Text(
                        '$timeLabel：種別ごとに解く',
                        style: theme.textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w900),
                      ),
                    ),
                    IconButton(
                      onPressed: () => Navigator.of(context).pop(),
                      icon: const Icon(Icons.close_rounded),
                    ),
                  ],
                ),
                const SizedBox(height: 6),
                Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                    '必修・一般・状況設定から選べます',
                    style: theme.textTheme.bodySmall?.copyWith(
                      color: AppColors.textSecondary,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
                const SizedBox(height: 12),

                // リスト
                ...parts.map((p) {
                  final total = _totalByPartKey[p.partKey] ?? 0;
                  final solved = _solvedCountForPart(p);

                  return Padding(
                    padding: const EdgeInsets.only(bottom: 10),
                    child: InkWell(
                      borderRadius: BorderRadius.circular(14),
                      onTap: () {
                        Navigator.of(context).pop();
                        _openPart(p);
                      },
                      child: Container(
                        padding: const EdgeInsets.fromLTRB(14, 12, 12, 12),
                        decoration: BoxDecoration(
                          borderRadius: BorderRadius.circular(14),
                          border: Border.all(color: Colors.black12),
                        ),
                        child: Row(
                          children: [
                            Expanded(
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    '${p.label} $timeLabel',
                                    style: theme.textTheme.bodyMedium?.copyWith(
                                      fontWeight: FontWeight.w900,
                                    ),
                                  ),
                                  const SizedBox(height: 6),
                                  Text(
                                    '$solved問 / $total問 解答',
                                    style: theme.textTheme.bodySmall?.copyWith(
                                      color: AppColors.textSecondary,
                                      fontWeight: FontWeight.w800,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                            const Icon(Icons.chevron_right_rounded, color: AppColors.textSecondary),
                          ],
                        ),
                      ),
                    ),
                  );
                }).toList(),

                if (parts.isEmpty)
                  Padding(
                    padding: const EdgeInsets.symmetric(vertical: 18),
                    child: Text(
                      'この時間帯のデータが見つかりませんでした',
                      style: theme.textTheme.bodyMedium?.copyWith(color: AppColors.textSecondary),
                    ),
                  ),
              ],
            ),
          ),
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    final hasAm = _hasAnyDataForTime('午前');
    final hasPm = _hasAnyDataForTime('午後');

    return BaseScaffold(
      title: widget.examTitle,
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : ListView(
        padding: const EdgeInsets.fromLTRB(16, 14, 16, 24),
        children: [
          _totalCard(theme),
          const SizedBox(height: 14),

          _timeCard(
            theme,
            timeLabel: '午前',
            hasData: hasAm,
            solved: _solvedCountForTime('午前'),
            total: _totalCountForTime('午前'),
            onStart: hasAm ? () => _openTimeAll('午前') : null,
            onByType: hasAm ? () => _showPartsSheet('午前') : null,
          ),

          const SizedBox(height: 12),

          _timeCard(
            theme,
            timeLabel: '午後',
            hasData: hasPm,
            solved: _solvedCountForTime('午後'),
            total: _totalCountForTime('午後'),
            onStart: hasPm ? () => _openTimeAll('午後') : null,
            onByType: hasPm ? () => _showPartsSheet('午後') : null,
          ),

          if (!hasAm && !hasPm)
            Padding(
              padding: const EdgeInsets.only(top: 28),
              child: Center(
                child: Text(
                  'この年度の過去問データが見つかりませんでした。',
                  style: theme.textTheme.bodyMedium?.copyWith(
                    color: AppColors.textSecondary,
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }

  Widget _totalCard(ThemeData theme) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.fromLTRB(16, 12, 16, 12),
      decoration: BoxDecoration(
        color: theme.colorScheme.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: Colors.black12),
      ),
      child: Text(
        '総問題数：${widget.totalQuestions}問',
        style: theme.textTheme.bodyMedium?.copyWith(
          fontWeight: FontWeight.w700,
        ),
      ),
    );
  }

  Widget _timeCard(
      ThemeData theme, {
        required String timeLabel,
        required bool hasData,
        required int solved,
        required int total,
        required VoidCallback? onStart,
        required VoidCallback? onByType,
      }) {
    return Container(
      decoration: BoxDecoration(
        color: theme.colorScheme.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: Colors.black12),
      ),
      padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
      child: Opacity(
        opacity: hasData ? 1.0 : 0.45,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 上段：タイトル＋開始ボタン
            Row(
              children: [
                Expanded(
                  child: Text(
                    '$timeLabelの問題を解く',
                    style: theme.textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w900),
                  ),
                ),
                SizedBox(
                  height: 38,
                  child: ElevatedButton(
                    onPressed: onStart,
                    style: ElevatedButton.styleFrom(
                      backgroundColor: AppColors.primary,
                      foregroundColor: Colors.white,
                      elevation: 0,
                      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
                      padding: const EdgeInsets.symmetric(horizontal: 16),
                    ),
                    child: const Text(
                      '開始',
                      style: TextStyle(fontWeight: FontWeight.w900),
                    ),
                  ),
                ),
              ],
            ),

            const SizedBox(height: 10),

            // 進捗
            Text(
              hasData ? '$solved問 / $total問 解答' : 'データ未登録',
              style: theme.textTheme.bodySmall?.copyWith(
                color: AppColors.textSecondary,
                fontWeight: FontWeight.w800,
              ),
            ),

            // 種別リンク（副機能）
            if (hasData) ...[
              const SizedBox(height: 12),
              InkWell(
                borderRadius: BorderRadius.circular(12),
                onTap: onByType,
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 6),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const Icon(Icons.tune_rounded, size: 18, color: AppColors.primary),
                      const SizedBox(width: 6),
                      Text(
                        '種別ごとに問題を解く',
                        style: theme.textTheme.bodySmall?.copyWith(
                          color: AppColors.primary,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                      const SizedBox(width: 2),
                      const Icon(Icons.chevron_right_rounded, color: AppColors.primary, size: 18),
                    ],
                  ),
                ),
              ),
            ],
          ],
        ),
      ),
    );
  }
}

class _PartMeta {
  final String partKey;
  final String label;     // 必修問題 / 一般問題 / 状況設定問題（時間は別で付ける）
  final String timeLabel; // 午前/午後

  const _PartMeta({
    required this.partKey,
    required this.label,
    required this.timeLabel,
  });
}

// lib/screens/past_exam/past_exam_my_answer_detail_screen.dart
import 'package:flutter/material.dart';

import '../../models/past_exam_history.dart';
import '../../theme/app_theme.dart';
import '../../widgets/base_scaffold.dart';

class PastExamMyAnswerDetailScreen extends StatelessWidget {
  const PastExamMyAnswerDetailScreen({
    super.key,
    required this.record,
  });

  final PastExamAnswerRecord record;

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    if (!record.hasSnapshot) {
      return BaseScaffold(
        title: '解答の詳細',
        body: const Center(
          child: Padding(
            padding: EdgeInsets.all(16),
            child: Text('この解答には復習用データ（問題文/選択肢）が保存されていません。'),
          ),
        ),
      );
    }

    final choices = record.choices ?? const <String, String>{};
    final correct = (record.correctLabels ?? const <String>[]).toSet();
    final selected = (record.selectedLabels ?? const <String>[]).toSet();

    // 根拠（choiceRationales）: Map<label, rationale>
    final rationales = record.rationales ?? const <String, String>{};

    return BaseScaffold(
      title: '解答の詳細',
      body: SingleChildScrollView(
        padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 520),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  record.examTitle ?? '',
                  style: theme.textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w800),
                ),
                const SizedBox(height: 4),
                Text(
                  '${record.partLabel ?? ''}${(record.questionNo ?? 0) > 0 ? ' ・ 第${record.questionNo}問' : ''}',
                  style: theme.textTheme.bodySmall?.copyWith(color: AppColors.textSecondary),
                ),
                const SizedBox(height: 12),

                // 問題文
                Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: theme.colorScheme.surface,
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(color: theme.colorScheme.outlineVariant.withOpacity(0.6)),
                  ),
                  child: Text(
                    record.questionText ?? '',
                    style: theme.textTheme.bodyMedium?.copyWith(height: 1.4),
                  ),
                ),

                // 画像
                if (record.hasImage) ...[
                  const SizedBox(height: 12),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: theme.colorScheme.surface,
                      borderRadius: BorderRadius.circular(16),
                      border: Border.all(color: theme.colorScheme.outlineVariant.withOpacity(0.6)),
                    ),
                    child: ClipRRect(
                      borderRadius: BorderRadius.circular(12),
                      child: InteractiveViewer(
                        minScale: 1.0,
                        maxScale: 4.0,
                        child: Image.asset(
                          record.imagePath!,
                          fit: BoxFit.contain,
                          errorBuilder: (_, __, ___) => Padding(
                            padding: const EdgeInsets.all(12),
                            child: Text(
                              '画像を読み込めません: ${record.imagePath}',
                              style: theme.textTheme.bodySmall?.copyWith(color: AppColors.textSecondary),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ],

                const SizedBox(height: 16),

                // 選択肢（根拠はここでは出さない）
                ...choices.entries.map((e) {
                  final label = e.key;
                  final text = e.value;

                  final isCorrect = correct.contains(label);
                  final isSelected = selected.contains(label);

                  Color border = Colors.black12;
                  Color bg = theme.colorScheme.surface;

                  if (isCorrect) {
                    border = Colors.green.withOpacity(0.7);
                    bg = Colors.green.withOpacity(0.06);
                  }
                  if (isSelected && !isCorrect) {
                    border = Colors.red.withOpacity(0.7);
                    bg = Colors.red.withOpacity(0.05);
                  }

                  return Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: Container(
                      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
                      decoration: BoxDecoration(
                        color: bg,
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(color: border),
                      ),
                      child: Row(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          SizedBox(
                            width: 26,
                            child: Text(
                              label,
                              style: theme.textTheme.bodyMedium?.copyWith(fontWeight: FontWeight.w800),
                            ),
                          ),
                          const SizedBox(width: 6),
                          Expanded(child: Text(text)),
                        ],
                      ),
                    ),
                  );
                }),

                const SizedBox(height: 12),

                // 解説（従来通り）
                if ((record.explanation ?? '').trim().isNotEmpty) ...[
                  Text('解説', style: theme.textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w800)),
                  const SizedBox(height: 6),
                  Text(
                    record.explanation!,
                    style: theme.textTheme.bodyMedium?.copyWith(height: 1.55),
                  ),
                  const SizedBox(height: 14),
                ],

                // ✅ 根拠（解説の下・解説と同フォント）
                if (rationales.isNotEmpty) ...[
                  Text('根拠', style: theme.textTheme.titleMedium?.copyWith(fontWeight: FontWeight.w800)),
                  const SizedBox(height: 6),

                  // ラベル順に並べたいので choices の順で出す（無いものはスキップ）
                  ...choices.keys.map((label) {
                    final r = (rationales[label] ?? '').trim();
                    if (r.isEmpty) return const SizedBox.shrink();

                    return Padding(
                      padding: const EdgeInsets.only(bottom: 8),
                      child: Text(
                        '$label：$r',
                        style: theme.textTheme.bodyMedium?.copyWith(height: 1.55),
                      ),
                    );
                  }).toList(),
                ],
              ],
            ),
          ),
        ),
      ),
    );
  }
}

// lib/screens/past_exam/past_exam_my_answers_list_screen.dart
import 'dart:async';

import 'package:flutter/material.dart';

import '../../models/past_exam_history.dart';
import '../../theme/app_theme.dart';
import '../../widgets/base_scaffold.dart';
import 'past_exam_my_answer_detail_screen.dart';

enum PastExamCorrectFilter {
  all,
  correct,
  wrong,
}

enum PastExamKindFilter {
  all,
  hisshu,
  ippan,
  situation,
}

enum PastExamTimeFilter {
  all,
  am,
  pm,
}

class PastExamMyAnswersListScreen extends StatefulWidget {
  const PastExamMyAnswersListScreen({
    super.key,
    required this.examId,
    required this.examTitle,
    required this.totalQuestions,
  });

  final String examId;
  final String examTitle;
  final int totalQuestions;

  @override
  State<PastExamMyAnswersListScreen> createState() =>
      _PastExamMyAnswersListScreenState();
}

class _PastExamMyAnswersListScreenState extends State<PastExamMyAnswersListScreen> {
  // ===== ちらつき対策：TextFieldの状態保持 =====
  late final TextEditingController _searchController;
  late final FocusNode _searchFocusNode;
  Timer? _debounce;

  // 検索キーワード（反映用）
  String _searchKeyword = '';

  // フィルタ
  PastExamCorrectFilter _correctFilter = PastExamCorrectFilter.all;
  PastExamKindFilter _kindFilter = PastExamKindFilter.all;
  PastExamTimeFilter _timeFilter = PastExamTimeFilter.all;

  // ===== 読み込み（buildでやらない） =====
  bool _loading = true;
  List<PastExamAnswerRecord> _allRecords = const [];

  late final VoidCallback _versionListener;

  @override
  void initState() {
    super.initState();

    _searchController = TextEditingController();
    _searchFocusNode = FocusNode();

    _versionListener = () {
      _load();
    };
    PastExamHistory.instance.versionListenable.addListener(_versionListener);

    _load();
  }

  @override
  void dispose() {
    PastExamHistory.instance.versionListenable.removeListener(_versionListener);
    _debounce?.cancel();
    _searchController.dispose();
    _searchFocusNode.dispose();
    super.dispose();
  }

  Future<void> _load() async {
    if (!mounted) return;
    setState(() => _loading = true);

    try {
      final list = await PastExamHistory.instance.recordsForExam(widget.examId);
      if (!mounted) return;
      setState(() {
        _allRecords = list;
        _loading = false;
      });
    } catch (_) {
      if (!mounted) return;
      setState(() {
        _allRecords = const [];
        _loading = false;
      });
    }
  }

  Future<void> _reloadPull() async {
    await _load();
  }

  // ---- kind推測（partKindが空でも label から拾う） ----
  String _inferPartKindFromLabel(String label) {
    final t = label.trim();
    if (t.contains('状況')) return '状況設定';
    if (t.contains('一般')) return '一般';
    if (t.contains('必修')) return '必修';
    return '';
  }

  String _normalizedKind(PastExamAnswerRecord r) {
    final raw = (r.partKind ?? '').trim();
    if (raw.isNotEmpty) return raw;
    return _inferPartKindFromLabel(r.partLabel ?? '');
  }

  // ---- 午前/午後推測 ----
  PastExamTimeFilter _inferTime(PastExamAnswerRecord r) {
    final t = '${r.partLabel ?? ''} ${r.partKind ?? ''}'.trim();
    if (t.contains('午前')) return PastExamTimeFilter.am;
    if (t.contains('午後')) return PastExamTimeFilter.pm;
    return PastExamTimeFilter.all;
  }

  bool _matchesTime(PastExamAnswerRecord r) {
    switch (_timeFilter) {
      case PastExamTimeFilter.all:
        return true;
      case PastExamTimeFilter.am:
        return _inferTime(r) == PastExamTimeFilter.am;
      case PastExamTimeFilter.pm:
        return _inferTime(r) == PastExamTimeFilter.pm;
    }
  }

  // ===== フィルタ適用 =====
  bool _matchesCorrect(PastExamAnswerRecord r) {
    switch (_correctFilter) {
      case PastExamCorrectFilter.all:
        return true;
      case PastExamCorrectFilter.correct:
        return r.isCorrect;
      case PastExamCorrectFilter.wrong:
        return !r.isCorrect;
    }
  }

  bool _matchesKind(PastExamAnswerRecord r) {
    final kind = _normalizedKind(r);
    switch (_kindFilter) {
      case PastExamKindFilter.all:
        return true;
      case PastExamKindFilter.hisshu:
        return kind.contains('必修');
      case PastExamKindFilter.ippan:
        return kind.contains('一般');
      case PastExamKindFilter.situation:
        return kind.contains('状況');
    }
  }

  bool _matchesSearch(PastExamAnswerRecord r, String q) {
    final needle = q.trim();
    if (needle.isEmpty) return true;

    final hay = <String>[
      r.questionKey,
      r.examTitle ?? '',
      r.partLabel ?? '',
      r.partKind ?? '',
      r.questionText ?? '',
      ...((r.choices ?? const <String, String>{}).values),
      ...((r.selectedLabels ?? const <String>[])),
      ...((r.correctLabels ?? const <String>[])),
    ].join('\n');

    return hay.contains(needle);
  }

  List<PastExamAnswerRecord> _applyFilter(List<PastExamAnswerRecord> items) {
    var list = List<PastExamAnswerRecord>.from(items);

    list = list.where((r) {
      return _matchesCorrect(r) &&
          _matchesKind(r) &&
          _matchesTime(r) &&
          _matchesSearch(r, _searchKeyword);
    }).toList();

    // recordsForExam は PastExamHistory 側で「新しい順」
    return list;
  }

  double _accuracyOf(Iterable<PastExamAnswerRecord> items) {
    if (items.isEmpty) return 0.0;
    final correct = items.where((r) => r.isCorrect).length;
    return correct / items.length;
  }

  String _pct(double v) => '${(v * 100).toStringAsFixed(1)}%';

  String _formatDateTime(DateTime dt) {
    final y = dt.year.toString().padLeft(4, '0');
    final m = dt.month.toString().padLeft(2, '0');
    final d = dt.day.toString().padLeft(2, '0');
    final hh = dt.hour.toString().padLeft(2, '0');
    final mm = dt.minute.toString().padLeft(2, '0');
    return '$y/$m/$d $hh:$mm';
  }

  Future<bool?> _confirmResetDialog(BuildContext context) {
    return showDialog<bool>(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text('解答履歴をリセットしますか？'),
        content: Text(
          '${widget.examTitle} の解答履歴がすべて削除されます。\n'
              'この操作は元に戻せません。',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(context).pop(false),
            child: const Text('キャンセル'),
          ),
          TextButton(
            onPressed: () => Navigator.of(context).pop(true),
            child: const Text(
              'リセット',
              style: TextStyle(color: Colors.red),
            ),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);

    final all = _allRecords;
    final items = _applyFilter(all);

    final correctCount = all.where((r) => r.isCorrect).length;
    final wrongCount = all.length - correctCount;
    final acc = _accuracyOf(all);

    final hasSituation = all.any((r) => _normalizedKind(r).contains('状況'));

    return BaseScaffold(
      title: widget.examTitle,
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : RefreshIndicator(
        onRefresh: _reloadPull,
        child: ListView.separated(
          padding: const EdgeInsets.fromLTRB(8, 8, 8, 24),
          itemCount: (all.isEmpty ? 1 : items.length + 1),
          separatorBuilder: (_, index) {
            if (index == 0) return const SizedBox(height: 8);
            return const Divider(height: 0);
          },
          itemBuilder: (context, index) {
            // ===== ヘッダー（常に表示） =====
            if (index == 0) {
              return Padding(
                padding: const EdgeInsets.fromLTRB(8, 4, 8, 8),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    _headerCard(
                      theme,
                      total: all.length,
                      correct: correctCount,
                      wrong: wrongCount,
                      accuracy: acc,
                      onReset: all.isEmpty
                          ? null
                          : () async {
                        final ok =
                        await _confirmResetDialog(context);
                        if (ok != true) return;
                        await PastExamHistory.instance
                            .resetExam(widget.examId);

                        if (!context.mounted) return;
                        ScaffoldMessenger.of(context).showSnackBar(
                          SnackBar(
                            content: Text(
                                '${widget.examTitle} の解答履歴をリセットしました'),
                          ),
                        );
                      },
                    ),
                    const SizedBox(height: 12),
                    _searchAndFilterBar(
                      theme,
                      hasSituation: hasSituation,
                    ),
                    if (all.isEmpty) ...[
                      const SizedBox(height: 20),
                      Center(
                        child: Text(
                          'まだ解答履歴がありません',
                          style: theme.textTheme.bodyMedium?.copyWith(
                            color: AppColors.textSecondary,
                          ),
                        ),
                      ),
                    ] else if (items.isEmpty) ...[
                      const SizedBox(height: 20),
                      Center(
                        child: Text(
                          '検索条件に一致する解答履歴が見つかりませんでした',
                          style: theme.textTheme.bodyMedium?.copyWith(
                            color: AppColors.textSecondary,
                          ),
                        ),
                      ),
                    ] else ...[
                      const SizedBox(height: 10),
                      Padding(
                        padding: const EdgeInsets.only(left: 4),
                        child: Text(
                          '表示：${items.length}件',
                          style: theme.textTheme.bodySmall?.copyWith(
                            color: AppColors.textSecondary,
                          ),
                        ),
                      ),
                    ],
                  ],
                ),
              );
            }

            // データなしならヘッダーのみ
            if (all.isEmpty || items.isEmpty) {
              return const SizedBox.shrink();
            }

            final r = items[index - 1];
            return _buildRow(context, theme, r);
          },
        ),
      ),
    );
  }

  // ===== UI部品 =====

  Widget _headerCard(
      ThemeData theme, {
        required int total,
        required int correct,
        required int wrong,
        required double accuracy,
        required VoidCallback? onReset,
      }) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.fromLTRB(16, 12, 12, 12),
      decoration: BoxDecoration(
        color: theme.colorScheme.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: Colors.black12),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  '解答履歴（過去問）',
                  style: theme.textTheme.titleMedium?.copyWith(
                    fontWeight: FontWeight.w700,
                  ),
                ),
                const SizedBox(height: 4),
                Text(
                  '解答数：$total 問   /   正答率：${_pct(accuracy)}',
                  style: theme.textTheme.bodySmall?.copyWith(
                    color: AppColors.textSecondary,
                  ),
                ),
                const SizedBox(height: 6),
                Text(
                  '内訳：正解 $correct ・ 不正解 $wrong',
                  style: theme.textTheme.bodySmall?.copyWith(
                    color: AppColors.textSecondary,
                  ),
                ),
              ],
            ),
          ),
          TextButton.icon(
            onPressed: onReset,
            style: TextButton.styleFrom(
              foregroundColor: theme.colorScheme.error,
            ),
            icon: const Icon(Icons.restart_alt_rounded, size: 18),
            label: const Text('リセット'),
          ),
        ],
      ),
    );
  }

  Widget _searchAndFilterBar(
      ThemeData theme, {
        required bool hasSituation,
      }) {
    return Column(
      children: [
        // 検索（debounceで“止まった瞬間だけ反映”）
        TextField(
          controller: _searchController,
          focusNode: _searchFocusNode,
          decoration: InputDecoration(
            hintText: '問題文・選択肢・パート名などで検索',
            prefixIcon: const Icon(Icons.search),
            isDense: true,
            border: const OutlineInputBorder(),
            suffixIcon: _searchController.text.trim().isEmpty
                ? null
                : IconButton(
              onPressed: () {
                _debounce?.cancel();
                _searchController.clear();
                setState(() => _searchKeyword = '');
              },
              icon: const Icon(Icons.clear_rounded),
            ),
          ),
          onChanged: (value) {
            _debounce?.cancel();
            _debounce = Timer(const Duration(milliseconds: 150), () {
              if (!mounted) return;
              setState(() {
                _searchKeyword = value;
              });
            });
          },
        ),
        const SizedBox(height: 8),

        // 既存（種別/正誤）の並びは維持
        Row(
          children: [
            // ===== 種別（左） =====
            Expanded(
              child: DropdownButtonFormField<PastExamKindFilter>(
                value: _kindFilter,
                decoration: const InputDecoration(
                  labelText: '種別',
                  isDense: true,
                  border: OutlineInputBorder(),
                ),
                items: [
                  const DropdownMenuItem(
                    value: PastExamKindFilter.all,
                    child: Text('全パート'),
                  ),
                  const DropdownMenuItem(
                    value: PastExamKindFilter.hisshu,
                    child: Text('必修のみ'),
                  ),
                  const DropdownMenuItem(
                    value: PastExamKindFilter.ippan,
                    child: Text('一般のみ'),
                  ),
                  if (hasSituation)
                    const DropdownMenuItem(
                      value: PastExamKindFilter.situation,
                      child: Text('状況設定のみ'),
                    ),
                ],
                onChanged: (v) {
                  if (v == null) return;
                  setState(() => _kindFilter = v);
                },
              ),
            ),

            const SizedBox(width: 8),

            // ===== 正誤（右） =====
            Expanded(
              child: DropdownButtonFormField<PastExamCorrectFilter>(
                value: _correctFilter,
                decoration: const InputDecoration(
                  labelText: '正誤',
                  isDense: true,
                  border: OutlineInputBorder(),
                ),
                items: const [
                  DropdownMenuItem(
                    value: PastExamCorrectFilter.all,
                    child: Text('すべて'),
                  ),
                  DropdownMenuItem(
                    value: PastExamCorrectFilter.correct,
                    child: Text('正解のみ'),
                  ),
                  DropdownMenuItem(
                    value: PastExamCorrectFilter.wrong,
                    child: Text('不正解のみ'),
                  ),
                ],
                onChanged: (v) {
                  if (v == null) return;
                  setState(() => _correctFilter = v);
                },
              ),
            ),
          ],
        ),

        const SizedBox(height: 8),

        // ✅ 追加：午前/午後（UIの雰囲気は崩さず、1段追加）
        DropdownButtonFormField<PastExamTimeFilter>(
          value: _timeFilter,
          decoration: const InputDecoration(
            labelText: '午前・午後',
            isDense: true,
            border: OutlineInputBorder(),
          ),
          items: const [
            DropdownMenuItem(
              value: PastExamTimeFilter.all,
              child: Text('すべて'),
            ),
            DropdownMenuItem(
              value: PastExamTimeFilter.am,
              child: Text('午前'),
            ),
            DropdownMenuItem(
              value: PastExamTimeFilter.pm,
              child: Text('午後'),
            ),
          ],
          onChanged: (v) {
            if (v == null) return;
            setState(() => _timeFilter = v);
          },
        ),
      ],
    );
  }

  Widget _buildRow(BuildContext context, ThemeData theme, PastExamAnswerRecord r) {
    final kind = _normalizedKind(r);
    final part = (r.partLabel ?? '').trim();
    final no = r.questionNo ?? 0;
    final when = _formatDateTime(r.ts);

    final title = (r.questionText ?? '').trim();
    final showTitle = title.isNotEmpty ? title : r.questionKey;

    final leadingIcon = Icon(
      r.isCorrect ? Icons.check_circle_outline : Icons.cancel_outlined,
      color: r.isCorrect ? Colors.green[600] : Colors.red[500],
    );

    final meta = [
      if (kind.isNotEmpty) kind,
      if (part.isNotEmpty) part,
      if (no > 0) '第$no問',
    ].join(' ・ ');

    return ListTile(
      leading: leadingIcon,
      title: Text(
        showTitle,
        maxLines: 2,
        overflow: TextOverflow.ellipsis,
      ),
      subtitle: Text('$when${meta.isEmpty ? '' : ' ・ $meta'}'),
      trailing: const Icon(Icons.chevron_right),
      onTap: () {
        Navigator.of(context).push(
          MaterialPageRoute(
            builder: (_) => PastExamMyAnswerDetailScreen(record: r),
          ),
        );
      },
    );
  }
}

