import 'dart:math';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';

import '../widgets/base_scaffold.dart';
import '../widgets/question_block.dart';
import '../widgets/question_controls.dart';

import '../services/category_repository.dart'; // 候補取得
import '../data/categories.dart'; // situationalDomains
import '../services/question_service.dart';
import '../models/answer_history.dart'; // 履歴保存
import 'result_screen.dart';

// ランダム指定用の内部ID（QuestionControls 側と揃える想定）
const String kRandomDomainId = '__RANDOM_DOMAIN__';
const String kRandomMajorId = '__RANDOM_MAJOR__';

// 分野・大項目・中項目をまとめて返すための小さな内部モデル
class _ResolvedCategory {
  final String domain;
  final String major;
  final String? mid;
  const _ResolvedCategory(this.domain, this.major, this.mid);
}

class QuestionScreen extends StatefulWidget {
  const QuestionScreen({super.key});
  @override
  State<QuestionScreen> createState() => _QuestionScreenState();
}

class _QuestionScreenState extends State<QuestionScreen> {
  // 出題形式
  static const String modeHisshu = '必修問題';
  static const String modeGeneral = '一般問題';
  static const String modeSituational = '状況設定問題';

  // 状況設定の観点
  static const Map<String, String> _scenarioAspects = {
    'A': 'A. 対象や家族に切れ目のない支援を提供するための継続した看護',
    'B': 'B. 複合的な状況にある対象や、複合的に提供されている看護の状況を判断し、危険を回避する取組み',
    'C': 'C. 看護の提供者が、看護場面において自身の安全を確保するための総合的な判断や対応',
    'D': 'D. 発災からの経過に応じて被災者に提供される診療や支援を促進するための看護',
    'E': 'E. A～Dを促進するための多職種連携',
  };

  String _mode = modeHisshu;

  // 一般／状況設定 共通の選択（UI 上の値）
  String _selectedDomain = CategoryRepository.generalDomains().isNotEmpty
      ? CategoryRepository.generalDomains().first
      : '';
  String _selectedMajor = CategoryRepository.generalMajorsOf(
    CategoryRepository.generalDomains().isNotEmpty
        ? CategoryRepository.generalDomains().first
        : '',
  ).isNotEmpty
      ? CategoryRepository.generalMajorsOf(
    CategoryRepository.generalDomains().isNotEmpty
        ? CategoryRepository.generalDomains().first
        : '',
  ).first
      : '';
  String? _selectedMid; // 任意指定（nullなら裏でランダム）

  // 必修
  String _selectedHisshuMajor = '';
  List<String> get hisshuMajorItems => CategoryRepository.hisshuMajorItems();

  // 状況設定：観点
  String? _selectedScenarioAspectCode;

  // 画面状態
  bool _isLoading = false;

  // 出題中データ
  String? _questionText;
  Map<String, String>? _choices;
  List<String>? _correctAnswers; // 複数対応
  String? _explanation;
  Map<String, String>? _rationales;
  Set<String> _userAnswers = {}; // 複数対応
  String _questionKind = 'single'; // 'single' | 'multiple' | 'select_incorrect'

  // 中項目を明示指定するか
  bool _useMid = false;

  // 履歴保存用メタ
  Map<String, dynamic>? _meta;

  @override
  void initState() {
    super.initState();
    _selectedHisshuMajor =
    hisshuMajorItems.isNotEmpty ? hisshuMajorItems.first : '';
    _resetGeneralMajorAndMid(_selectedDomain);
  }

  void _resetGeneralMajorAndMid(String domain) {
    final ms = CategoryRepository.generalMajorsOf(domain);
    final newMajor = ms.isNotEmpty ? ms.first : '';
    final mids = (newMajor.isEmpty)
        ? const <String>[]
        : CategoryRepository.generalMidsOf(domain, newMajor);
    setState(() {
      _selectedDomain = domain;
      _selectedMajor = newMajor;
      _selectedMid = mids.isNotEmpty ? mids.first : null;
    });
  }

  String _randomScenarioAspectCode() {
    const keys = ['A', 'B', 'C', 'D', 'E'];
    return keys[Random().nextInt(keys.length)];
  }

  // ==========================
  // 分野・大項目・中項目の最終決定
  // （ランダムで決まった結果もここで確定させる）
  // ==========================
  _ResolvedCategory _resolveCategoryForGeneration() {
    // 必修はこの関数は経由しない想定（_generateQuestion 側で処理）
    if (_mode == modeHisshu) {
      return _ResolvedCategory('必修', _selectedHisshuMajor, null);
    }

    final List<String> domainList = _mode == modeSituational
        ? situationalDomains
        : CategoryRepository.generalDomains();

    final rand = Random(DateTime.now().microsecondsSinceEpoch);

    // ↓ ユーザーが「ランダム」を選んだかどうかのフラグ
    final bool domainRandomRequested = _selectedDomain == kRandomDomainId;
    final bool majorRandomRequested = _selectedMajor == kRandomMajorId;

    // ---- 分野 ----
    String domain = _selectedDomain;
    if (domainRandomRequested || !domainList.contains(domain)) {
      if (domainList.isNotEmpty) {
        domain = domainList[rand.nextInt(domainList.length)];
      } else {
        domain = '';
      }
    }

    // ---- 大項目 ----
    final majorsOfDomain = CategoryRepository.generalMajorsOf(domain);
    String major = _selectedMajor;
    if (majorRandomRequested ||
        major.isEmpty ||
        !majorsOfDomain.contains(major)) {
      if (majorsOfDomain.isNotEmpty) {
        major = majorsOfDomain[rand.nextInt(majorsOfDomain.length)];
      } else {
        major = '';
      }
    }

    // ---- 中項目 ----
    String? mid;
    bool midRandomUsed = false;
    if (_useMid) {
      final mids = CategoryRepository.generalMidsOf(domain, major);
      if (_selectedMid != null &&
          _selectedMid!.isNotEmpty &&
          mids.contains(_selectedMid)) {
        mid = _selectedMid;
      } else if (mids.isNotEmpty) {
        midRandomUsed = true;
        mid = mids[rand.nextInt(mids.length)];
      }
    } else {
      mid = null;
    }

    // ▼ ログ出力（ランダム指定がどう解決されたかを確認できる）
    debugPrint(
      '[log] [QSCREEN] resolved category '
          '(mode=$_mode, domainRandom=$domainRandomRequested, '
          'majorRandom=$majorRandomRequested, midRandom=$midRandomUsed) '
          '=> domain="$domain", major="$major", mid="${mid ?? '(none)'}"',
    );

    return _ResolvedCategory(domain, major, mid);
  }

  Future<void> _generateQuestion() async {
    setState(() {
      _isLoading = true;
      _questionText = null;
      _choices = null;
      _correctAnswers = null;
      _explanation = null;
      _rationales = null;
      _userAnswers = {};
      _questionKind = 'single';
      _meta = null;
    });

    try {
      final difficulty = _mode;

      late final String domainArg;
      late final String majorArg;
      String? midArg;
      String? scenarioAspectCode;

      if (_mode == modeHisshu) {
        // 必修は分野「必修」、大項目は UI 選択値そのまま
        domainArg = '必修';
        majorArg = _selectedHisshuMajor;
        midArg = null;

        debugPrint(
          '[log] [QS] category resolved (hisshu) => '
              'mode=$_mode | domain=$domainArg | major=$majorArg | mid=(none)',
        );
      } else {
        // 一般／状況設定はランダム指定を解決
        final resolved = _resolveCategoryForGeneration();
        domainArg = resolved.domain;
        majorArg = resolved.major;
        midArg = resolved.mid;

        if (_mode == modeSituational) {
          final bool wasRandomAspect = _selectedScenarioAspectCode == null;
          scenarioAspectCode =
              _selectedScenarioAspectCode ?? _randomScenarioAspectCode();

          debugPrint(
            '[log] [QS] scenarioAspect resolved => '
                'mode=$_mode | aspect=$scenarioAspectCode'
                '${wasRandomAspect ? " (random)" : " (selected)"}',
          );
        }
      }

      final data = await QuestionService.fetchQuestion(
        difficulty: difficulty,
        domain: domainArg,
        major: majorArg,
        mid: midArg,
        scenarioAspect: scenarioAspectCode,
      );

      setState(() {
        _questionText = (data['question'] as String?)?.trim();

        // choices（Map<String,String>）へ正規化
        final rawChoices = data['choices'] as Map?;
        _choices =
            rawChoices?.map((k, v) => MapEntry(k.toString(), v.toString()));

        // 正解（複数対応）
        _correctAnswers = (data['correctAnswers'] as List?)
            ?.map((e) => e.toString())
            .toList() ??
            [(data['correct'] ?? '').toString()];

        // 問題タイプ
        _questionKind = (data['questionKind'] as String?) ?? 'single';

        _explanation = (data['explanation'] as String?) ?? '';
        final rawRat = data['rationales'] as Map?;
        _rationales =
            rawRat?.map((k, v) => MapEntry(k.toString(), v.toString()));

        final rawMeta = data['meta'] as Map?;
        _meta = rawMeta?.map((k, v) => MapEntry(k.toString(), v));
      });
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('問題の生成に失敗しました：$e')),
      );
    } finally {
      if (mounted) {
        setState(() => _isLoading = false);
      }
    }
  }

  Future<void> _submitAnswer() async {
    if (_questionText == null || _choices == null || _correctAnswers == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('問題を生成してから解答してください。')),
      );
      return;
    }
    if (_userAnswers.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('選択肢を選んでください。')),
      );
      return;
    }

    // 履歴保存（複数解答対応）
    try {
      final rec = AnswerRecord(
        id: DateTime.now().millisecondsSinceEpoch.toString(),
        ts: DateTime.now(),
        difficulty: _mode,
        domain: (_meta?['domain'] as String?) ?? _selectedDomain,
        major: (_meta?['major'] as String?) ?? _selectedMajor,
        mid: (_meta?['mid'] as String?) ?? (_useMid ? _selectedMid : null),
        topic: _meta?['topic'] as String?,
        question: _questionText!,
        choices: _choices!,
        explanation: _explanation,
        rationales: _rationales,
        choiceCount: _choices!.length,
        questionKind: _questionKind,
        userAnswers: _userAnswers.toList()..sort(),
        correctAnswers: _correctAnswers!..sort(),
      );
      await AnswerHistory.instance.add(rec);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('履歴の保存に失敗しました：$e')),
        );
      }
    }

    if (!mounted) return;

    // 結果画面へ
    Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => ResultScreen(
          question: _questionText!,
          choices: _choices!,
          selectedAnswers: _userAnswers.toList(),
          correctAnswers: _correctAnswers!,
          explanation: _explanation ?? '',
          rationales: _rationales,
          onGenerateNext: _generateQuestion,
          difficulty: _mode,
          domain: _meta?['domain'] as String?,
          major: _meta?['major'] as String?,
          mid: _meta?['mid'] as String?,
          topic: _meta?['topic'] as String?,
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final domainList = _mode == modeSituational
        ? situationalDomains
        : CategoryRepository.generalDomains();

    // select_incorrect も含めて「正答が複数」ならチェックボックスモード
    final bool isMulti = _questionKind == 'multiple' ||
        _questionKind == 'select_incorrect' ||
        (_correctAnswers?.length ?? 0) >= 2;

    return BaseScaffold(
      title: '出題',
      body: SafeArea(
        child: SingleChildScrollView(
          padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              // ====== コントロール部 ======
              QuestionControls(
                mode: _mode,
                onModeChanged: (val) {
                  setState(() {
                    _mode = val;
                    if (_mode != modeHisshu) {
                      final useList = _mode == modeSituational
                          ? situationalDomains
                          : CategoryRepository.generalDomains();
                      final dom = useList.contains(_selectedDomain)
                          ? _selectedDomain
                          : (useList.isNotEmpty
                          ? useList.first
                          : _selectedDomain);
                      _resetGeneralMajorAndMid(dom);
                    }
                  });
                },
                isLoading: _isLoading,
                onGeneratePressed: _generateQuestion,

                // 一般/状況設定
                domainItems: domainList,
                selectedDomain: domainList.contains(_selectedDomain)
                    ? _selectedDomain
                    : (domainList.isNotEmpty
                    ? domainList.first
                    : _selectedDomain),
                onDomainChanged: (val) => _resetGeneralMajorAndMid(val),
                majorItems:
                CategoryRepository.generalMajorsOf(_selectedDomain),
                selectedMajor: _selectedMajor,
                onMajorChanged: (val) {
                  final mids =
                  CategoryRepository.generalMidsOf(_selectedDomain, val);
                  setState(() {
                    _selectedMajor = val;
                    _selectedMid = mids.isNotEmpty ? mids.first : null;
                  });
                },
                useMid: _useMid,
                onUseMidChanged: (v) => setState(() => _useMid = v),
                midItems: CategoryRepository.generalMidsOf(
                    _selectedDomain, _selectedMajor),
                selectedMid: _selectedMid,
                onMidChanged: (val) => setState(() => _selectedMid = val),

                // 必修
                hisshuMajorItems: hisshuMajorItems,
                selectedHisshuMajor:
                hisshuMajorItems.contains(_selectedHisshuMajor)
                    ? _selectedHisshuMajor
                    : (hisshuMajorItems.isNotEmpty
                    ? hisshuMajorItems.first
                    : ''),
                onHisshuMajorChanged: (val) =>
                    setState(() => _selectedHisshuMajor = val),

                // 状況設定
                scenarioAspects: _scenarioAspects,
                selectedScenarioAspectCode: _selectedScenarioAspectCode,
                onScenarioAspectChanged: (val) =>
                    setState(() => _selectedScenarioAspectCode = val),
              ),

              const SizedBox(height: 24),

              // ====== 出題ブロック ======
              if (_questionText != null && _choices != null)
                QuestionBlock(
                  questionText: _questionText!,
                  choices: _choices!,
                  questionKind: _questionKind,

                  // 単一選択
                  selectedLabel: !isMulti && _userAnswers.isNotEmpty
                      ? _userAnswers.first
                      : null,
                  onSelect: !isMulti
                      ? (val) => setState(() => _userAnswers = {val})
                      : null,

                  // 複数選択（select_incorrect を含む）
                  selectedLabels: isMulti ? _userAnswers.toList() : null,
                  onToggle: isMulti
                      ? (val) {
                    setState(() {
                      if (_userAnswers.contains(val)) {
                        _userAnswers.remove(val);
                      } else {
                        _userAnswers.add(val);
                      }
                    });
                  }
                      : null,

                  onSubmit: _submitAnswer,
                ),
            ],
          ),
        ),
      ),
    );
  }
}

// lib/screens/result_screen.dart
import 'package:flutter/material.dart';

import '../widgets/base_scaffold.dart';
import '../widgets/app_buttons.dart';
import '../widgets/result_block.dart';

class ResultScreen extends StatefulWidget {
  final String question;
  final Map<String, String> choices;

  /// 複数対応（単一の場合も1要素で渡る）
  final List<String> selectedAnswers;
  final List<String> correctAnswers;

  final String explanation;
  final Map<String, String>? rationales;

  /// 次の問題を生成（QuestionScreen 側から渡される）
  final VoidCallback onGenerateNext;

  /// メタ（任意）
  final String? difficulty;
  final String? domain;
  final String? major;
  final String? mid;
  final String? topic;

  /// 問題タイプ（'single' | 'multiple' | 'select_incorrect'）
  /// 渡されない場合は 'single' として扱う（後方互換）
  final String? questionKind;

  const ResultScreen({
    super.key,
    required this.question,
    required this.choices,
    required this.selectedAnswers,
    required this.correctAnswers,
    required this.explanation,
    this.rationales,
    required this.onGenerateNext,
    this.difficulty,
    this.domain,
    this.major,
    this.mid,
    this.topic,
    this.questionKind,
  });

  @override
  State<ResultScreen> createState() => _ResultScreenState();
}

class _ResultScreenState extends State<ResultScreen> {
  bool _showOverlay = false;
  bool _isCorrect = false;

  @override
  void initState() {
    super.initState();
    _isCorrect = _isFullyCorrect();
    _showOverlay = true;

    // 画面描画後にフェードアウトを開始
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _scheduleOverlayHide();
    });
  }

  /// 完全一致方式の正誤判定
  bool _isFullyCorrect() {
    final sel = widget.selectedAnswers.toSet();
    final cor = widget.correctAnswers.toSet();
    if (sel.isEmpty || cor.isEmpty) return false;
    if (sel.length != cor.length) return false;
    return sel.containsAll(cor);
  }

  void _scheduleOverlayHide() async {
    // 表示時間 ＋ フェードアウト時間はお好みで調整可
    await Future.delayed(const Duration(milliseconds: 900));
    if (!mounted) return;
    setState(() {
      _showOverlay = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    final kind = widget.questionKind ?? 'single';

    // ★ select_incorrect のときに解説テキストを正しいラベルで補正する
    final normalizedExplanation = _normalizeExplanation(
      explanation: widget.explanation,
      correctAnswers: widget.correctAnswers,
      questionKind: kind,
    );

    return Stack(
      children: [
        BaseScaffold(
          title: '解答結果',
          body: SafeArea(
            child: SingleChildScrollView(
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  ResultBlock(
                    question: widget.question,
                    choices: widget.choices,
                    selectedAnswers: widget.selectedAnswers,
                    correctAnswers: widget.correctAnswers,
                    explanation: normalizedExplanation,
                    rationales: widget.rationales,
                    questionKind: kind,
                  ),
                  const SizedBox(height: 20),

                  // 次の問題
                  SizedBox(
                    width: double.infinity,
                    child: AppButtons.success(
                      label: '次の問題を生成',
                      icon: Icons.refresh,
                      onPressed: () {
                        widget.onGenerateNext();
                        Navigator.of(context).pop();
                      },
                    ),
                  ),
                  const SizedBox(height: 10),

                  // 出題に戻る
                  SizedBox(
                    width: double.infinity,
                    child: AppButtons.primary(
                      label: '出題に戻る',
                      icon: Icons.arrow_back,
                      onPressed: () => Navigator.of(context).pop(),
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),

        // 正解 / 不正解 オーバーレイ
        _buildResultOverlay(context),
      ],
    );
  }

  /// 正解 / 不正解 を大きく表示するオーバーレイ
  Widget _buildResultOverlay(BuildContext context) {
    final theme = Theme.of(context);
    final color = _isCorrect ? Colors.green.shade600 : Colors.red.shade600;
    final symbol = _isCorrect ? '◯' : '✕';
    final label = _isCorrect ? '正解！' : '不正解';

    return IgnorePointer(
      child: AnimatedOpacity(
        opacity: _showOverlay ? 1.0 : 0.0,
        duration: const Duration(milliseconds: 600),
        child: Container(
          color: Colors.black.withOpacity(0.10),
          alignment: Alignment.center,
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              // ★ 下線の原因をなくすため TextHeightBehavior を指定
              RichText(
                textHeightBehavior: const TextHeightBehavior(
                  applyHeightToFirstAscent: false,
                  applyHeightToLastDescent: false,
                ),
                text: TextSpan(
                  text: symbol,
                  style: TextStyle(
                    fontSize: 130,
                    fontWeight: FontWeight.w900,
                    height: 0.8,              // ★ 行間をさらに詰める
                    color: color,
                  ),
                ),
              ),

              const SizedBox(height: 8),

              Text(
                label,
                textAlign: TextAlign.center,
                style: theme.textTheme.headlineMedium?.copyWith(
                  fontWeight: FontWeight.w900,
                  color: color,
                  height: 1.0,
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  /// explanation の整形
  ///
  /// - select_incorrect のときだけ、
  ///   「選択肢CとDが誤った記述です。」などの一文を先頭に挿入（or 置き換え）して
  ///   correctAnswers と必ず整合するようにする。
  String _normalizeExplanation({
    required String explanation,
    required List<String> correctAnswers,
    required String questionKind,
  }) {
    final trimmed = explanation.trim();
    if (trimmed.isEmpty) return '';

    if (questionKind != 'select_incorrect') {
      // 単純な正答問題（single / multiple）はそのまま使う
      return trimmed;
    }

    // 正しいラベル群（A, B, ...）をソートして結合
    final labels = correctAnswers.map((e) => e.trim()).where((e) => e.isNotEmpty).toSet().toList()
      ..sort();
    if (labels.isEmpty) return trimmed;

    final joined = _labelsToJoined(labels);
    final head = '選択肢$joinedが誤った記述です。';

    // もし先頭の一文が「選択肢○と△は誤った記述です」系なら、それを差し替え
    final firstPeriodIndex = trimmed.indexOf('。');
    if (firstPeriodIndex >= 0) {
      final firstSentence = trimmed.substring(0, firstPeriodIndex + 1);
      final rest = trimmed.substring(firstPeriodIndex + 1).trimLeft();

      if (firstSentence.contains('選択肢') &&
          (firstSentence.contains('誤った') ||
              firstSentence.contains('誤り') ||
              firstSentence.contains('誤っている'))) {
        // 先頭文を head に差し替え
        if (rest.isEmpty) {
          return head;
        }
        return '$head$rest';
      } else {
        // 先頭文が別物なら、head を前に足す
        return '$head$trimmed';
      }
    } else {
      // 句点が無ければ単純に前置
      return '$head$trimmed';
    }
  }

  /// ラベル配列を「A」「AとB」「A、BとC」形式に連結
  String _labelsToJoined(List<String> labels) {
    if (labels.isEmpty) return '';
    if (labels.length == 1) return labels.first;
    if (labels.length == 2) return '${labels[0]}と${labels[1]}';
    final head = labels.sublist(0, labels.length - 1).join('、');
    return '$headと${labels.last}';
  }
}

// lib/screens/score_screen.dart
import 'package:flutter/material.dart';

import '../models/answer_history.dart';
import '../widgets/base_scaffold.dart';
import '../widgets/history_charts.dart'; // MiniBarChart / buildBarItemsFromStatMap
import '../widgets/exam_score_summary_card.dart';
import '../theme/app_theme.dart';

class ScoreScreen extends StatefulWidget {
  const ScoreScreen({super.key});

  @override
  State<ScoreScreen> createState() => _ScoreScreenState();
}

class _ScoreScreenState extends State<ScoreScreen>
    with SingleTickerProviderStateMixin {
  late Future<List<AnswerRecord>> _future;

  String _filter = 'すべて'; // 'すべて' / '直近1週間' / '直近1ヶ月'

  late final AnimationController _animController;
  late final Animation<Offset> _slideAnim;

  @override
  void initState() {
    super.initState();
    _future = AnswerHistory.instance.all();

    // カード表示用のフェード＋スライドアニメーション
    _animController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 500),
    );
    _slideAnim = Tween<Offset>(
      begin: const Offset(0, 0.05),
      end: Offset.zero,
    ).animate(
      CurvedAnimation(
        parent: _animController,
        curve: Curves.easeOutCubic,
      ),
    );
    _animController.forward();
  }

  @override
  void dispose() {
    _animController.dispose();
    super.dispose();
  }

  Future<void> _reload() async {
    setState(() {
      _future = AnswerHistory.instance.all();
    });
    await _future;
  }

  List<AnswerRecord> _applyFilter(List<AnswerRecord> items) {
    final now = DateTime.now();
    switch (_filter) {
      case '直近1週間':
        final from7 = now.subtract(const Duration(days: 7));
        return items.where((r) => r.ts.isAfter(from7)).toList();
      case '直近1ヶ月':
        final from30 = now.subtract(const Duration(days: 30));
        return items.where((r) => r.ts.isAfter(from30)).toList();
      default:
        return items; // すべて
    }
  }

  @override
  Widget build(BuildContext context) {
    return BaseScaffold(
      title: '成績',
      body: FutureBuilder<List<AnswerRecord>>(
        future: _future,
        builder: (context, snap) {
          if (snap.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }
          if (snap.hasError) {
            return Center(
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Text('読み込みに失敗しました: ${snap.error}'),
              ),
            );
          }

          final allItems = snap.data ?? const <AnswerRecord>[];

          // ★ AI学習成績のみを対象（過去問はスコア画面では扱わない）
          final trainingItems =
          allItems.where((r) => r.sourceType != 'past_exam').toList();

          final filteredTraining = _applyFilter(trainingItems);

          return RefreshIndicator(
            onRefresh: _reload,
            child: ListView(
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
              children: [
                _buildFilterDropdown(),
                const SizedBox(height: 16),
                if (filteredTraining.isEmpty)
                  const Padding(
                    padding: EdgeInsets.only(top: 40),
                    child: Center(child: Text('該当する解答履歴がありません')),
                  )
                else
                  _buildTrainingContent(filteredTraining),
              ],
            ),
          );
        },
      ),
    );
  }

  // ============================
  //  トレーニング成績（AI問題）
  // ============================

  Widget _buildTrainingContent(List<AnswerRecord> items) {
    final theme = Theme.of(context);

    // ===== 集計 =====
    final total = items.length;
    final correct = items.where((r) => r.isCorrect).length;
    final rate = (total == 0) ? 0.0 : (correct / total);

    // 出題形式別
    final byDifficulty = <String, Map<String, int>>{};
    for (final r in items) {
      byDifficulty.putIfAbsent(r.difficulty, () => {'total': 0, 'correct': 0});
      byDifficulty[r.difficulty]!['total'] =
          (byDifficulty[r.difficulty]!['total'] ?? 0) + 1;
      if (r.isCorrect) {
        byDifficulty[r.difficulty]!['correct'] =
            (byDifficulty[r.difficulty]!['correct'] ?? 0) + 1;
      }
    }

    // 分野別
    final byDomain = <String, Map<String, int>>{};
    for (final r in items) {
      final dom = (r.domain == null || r.domain!.isEmpty) ? '未指定' : r.domain!;
      byDomain.putIfAbsent(dom, () => {'total': 0, 'correct': 0});
      byDomain[dom]!['total'] = (byDomain[dom]!['total'] ?? 0) + 1;
      if (r.isCorrect) {
        byDomain[dom]!['correct'] = (byDomain[dom]!['correct'] ?? 0) + 1;
      }
    }

    // 出題形式 × 分野
    final byDifficultyDomain = <String, Map<String, Map<String, int>>>{};
    for (final r in items) {
      final diff = r.difficulty;
      final dom = (r.domain == null || r.domain!.isEmpty) ? '未指定' : r.domain!;
      byDifficultyDomain.putIfAbsent(diff, () => <String, Map<String, int>>{});
      byDifficultyDomain[diff]!
          .putIfAbsent(dom, () => {'total': 0, 'correct': 0});
      byDifficultyDomain[diff]![dom]!['total'] =
          (byDifficultyDomain[diff]![dom]!['total'] ?? 0) + 1;
      if (r.isCorrect) {
        byDifficultyDomain[diff]![dom]!['correct'] =
            (byDifficultyDomain[diff]![dom]!['correct'] ?? 0) + 1;
      }
    }

    const diffOrder = ['必修問題', '一般問題', '状況設定問題'];
    final diffKeys = [
      ...diffOrder.where((k) => byDifficultyDomain.containsKey(k)),
      ...byDifficultyDomain.keys.where((k) => !diffOrder.contains(k)).toList()
        ..sort(),
    ];

    // ===== 上段：国試スコアカード + テキスト統計カード =====
    final totalStat = _StatCard(
      title: '総合成績',
      lines: [
        '解答数：$total',
        '正解数：$correct',
        '正答率：${(rate * 100).toStringAsFixed(1)}%',
      ],
    );

    final diffLines = byDifficulty.entries.map((e) {
      final t = e.value['total'] ?? 0;
      final c = e.value['correct'] ?? 0;
      final r = t == 0 ? 0.0 : c / t;
      return '${e.key}：$c / $t（${(r * 100).toStringAsFixed(1)}%）';
    }).toList();

    final diffStat = _StatCard(title: '出題形式別', lines: diffLines);

    final topRow = LayoutBuilder(
      builder: (context, constraints) {
        final isNarrow = constraints.maxWidth < 420;
        if (isNarrow) {
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              SizedBox(width: double.infinity, child: totalStat),
              const SizedBox(height: 12),
              SizedBox(width: double.infinity, child: diffStat),
            ],
          );
        } else {
          return Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(child: totalStat),
              const SizedBox(width: 16),
              Expanded(child: diffStat),
            ],
          );
        }
      },
    );

    final trendCard = _buildTrendCard(items);

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // ★ 国試スコア（目安）カード
        ExamScoreSummaryCard(records: items),
        const SizedBox(height: 16),

        FadeTransition(
          opacity: _animController,
          child: SlideTransition(
            position: _slideAnim,
            child: topRow,
          ),
        ),

        const SizedBox(height: 16),

        if (trendCard != null) ...[
          FadeTransition(
            opacity: _animController,
            child: SlideTransition(
              position: _slideAnim,
              child: trendCard,
            ),
          ),
          const SizedBox(height: 24),
        ] else
          const SizedBox(height: 24),

        // ===== 分野別成績 =====
        Text('分野別成績', style: theme.textTheme.titleMedium),
        const SizedBox(height: 8),
        _expansionCard(
          title: '正答率（分野別）',
          child: MiniBarChart(
            title: null,
            items: buildBarItemsFromStatMap(byDomain),
            barHeight: 20,
            maxItems: 10,
          ),
        ),

        const SizedBox(height: 16),

        // ===== 出題形式 × 分野 =====
        Text('出題形式 × 分野', style: theme.textTheme.titleMedium),
        const SizedBox(height: 8),
        _expansionCard(
          title: '出題形式ごとの分野別正答率',
          child: Column(
            children: diffKeys.map((diff) {
              final domainStats =
                  byDifficultyDomain[diff] ?? const <String, Map<String, int>>{};
              if (domainStats.isEmpty) {
                return Padding(
                  padding: const EdgeInsets.symmetric(vertical: 6),
                  child: Align(
                    alignment: Alignment.centerLeft,
                    child: Text('$diff：データなし'),
                  ),
                );
              }
              return Padding(
                padding: const EdgeInsets.only(bottom: 12),
                child: MiniBarChart(
                  title: '$diff の分野別正答率',
                  items: buildBarItemsFromStatMap(domainStats),
                  barHeight: 18,
                  maxItems: 8,
                ),
              );
            }).toList(),
          ),
        ),
      ],
    );
  }

  /// 日毎の正答率推移カード（直近10日分）
  Widget? _buildTrendCard(List<AnswerRecord> items) {
    if (items.isEmpty) return null;

    final buckets = <DateTime, _TrendBucket>{};
    for (final r in items) {
      final day = DateTime(r.ts.year, r.ts.month, r.ts.day);
      final bucket = buckets.putIfAbsent(day, () => _TrendBucket());
      bucket.total++;
      if (r.isCorrect) bucket.correct++;
    }

    var keys = buckets.keys.toList()..sort();
    const maxDays = 10;
    if (keys.length > maxDays) {
      keys = keys.sublist(keys.length - maxDays);
    }

    final points = <_TrendPoint>[];
    for (final d in keys) {
      final b = buckets[d]!;
      final acc = b.total == 0 ? 0.0 : b.correct / b.total;
      final label = '${d.month}/${d.day}';
      points.add(_TrendPoint(label: label, accuracy: acc));
    }

    if (points.isEmpty) return null;

    final theme = Theme.of(context);
    final cs = theme.colorScheme;

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: cs.surface,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: cs.outlineVariant.withOpacity(0.6)),
        boxShadow: const [
          BoxShadow(
            color: Colors.black12,
            blurRadius: 4,
            offset: Offset(0, 2),
          ),
        ],
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            '正答率の推移（直近${points.length}日）',
            style: theme.textTheme.titleMedium,
          ),
          const SizedBox(height: 12),
          SizedBox(
            height: 120,
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.end,
              children: points.map((p) {
                final value = p.accuracy.clamp(0.0, 1.0);
                final heightFactor = value == 0 ? 0.05 : value;
                return Expanded(
                  child: Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 4),
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.end,
                      children: [
                        Expanded(
                          child: Align(
                            alignment: Alignment.bottomCenter,
                            child: FractionallySizedBox(
                              heightFactor: heightFactor,
                              alignment: Alignment.bottomCenter,
                              child: Container(
                                decoration: BoxDecoration(
                                  color: cs.primary.withOpacity(0.85),
                                  borderRadius: BorderRadius.circular(6),
                                ),
                              ),
                            ),
                          ),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          p.label,
                          style: theme.textTheme.bodySmall?.copyWith(fontSize: 10),
                        ),
                        Text(
                          '${(p.accuracy * 100).toStringAsFixed(0)}%',
                          style: theme.textTheme.bodySmall?.copyWith(
                            fontSize: 11,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              }).toList(),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildFilterDropdown() {
    return Row(
      children: [
        const Text('表示期間: '),
        const SizedBox(width: 8),
        DropdownButton<String>(
          value: _filter,
          items: const [
            DropdownMenuItem(value: 'すべて', child: Text('すべて')),
            DropdownMenuItem(value: '直近1週間', child: Text('直近1週間')),
            DropdownMenuItem(value: '直近1ヶ月', child: Text('直近1ヶ月')),
          ],
          onChanged: (val) {
            if (val != null) setState(() => _filter = val);
          },
        ),
      ],
    );
  }

  /// カード風 ExpansionTile
  Widget _expansionCard({required String title, required Widget child}) {
    final theme = Theme.of(context);
    final cs = theme.colorScheme;

    return Container(
      decoration: BoxDecoration(
        color: cs.surface,
        borderRadius: BorderRadius.circular(16),
